import queue
import threading

cola = queue.Queue(maxsize=10)
FIN = object()                      # centinela: «no hay más trabajo»

def productor():
    for n in range(20):
        cola.put(n)
    cola.put(FIN)

def consumidor(resultados):
    while (item := cola.get()) is not FIN:
        resultados.append(item * item)

resultados = []                     # solo el consumidor escribe en esta lista
hilos = [threading.Thread(target=productor),
         threading.Thread(target=consumidor, args=(resultados,))]
for h in hilos:
    h.start()
for h in hilos:
    h.join()
print(resultados[:5])               # [0, 1, 4, 9, 16]

