import math
from concurrent.futures import ProcessPoolExecutor, as_completed

def es_primo(n):
    if n < 2:
        return False
    return all(n % d for d in range(2, math.isqrt(n) + 1))

NUMEROS = [112272535095293, 112582705942171, 115280095190773, 1099726899285419]

def main():
    # CPU-bound → procesos. Para E/S bastaría con cambiarlo por ThreadPoolExecutor
    with ProcessPoolExecutor() as ejecutor:
        futuros = {ejecutor.submit(es_primo, n): n for n in NUMEROS}
        for futuro in as_completed(futuros):       # según van terminando
            n = futuros[futuro]
            print(n, "es primo" if futuro.result() else "no es primo")

        print(list(ejecutor.map(es_primo, NUMEROS)))   # map conserva el orden

if __name__ == "__main__":
    main()

