import asyncio


async def consultar_precios(productos, consultar):
    unicos = list(dict.fromkeys(productos))      # sin repetidos y en orden
    async with asyncio.TaskGroup() as tg:
        tareas = {producto: tg.create_task(consultar(producto)) for producto in unicos}
    return {producto: tarea.result() for producto, tarea in tareas.items()}

