import asyncio
import time

PRECIOS = {"pan": 1.2, "leche": 0.95, "cafe": 4.5, "arroz": 1.1}

class Tienda:
    def __init__(self, retrasos=None):
        self.retrasos = retrasos or {}
        self.llamadas = []
        self.canceladas = []

    async def consultar(self, producto):
        self.llamadas.append(producto)
        try:
            await asyncio.sleep(self.retrasos.get(producto, 0.1))
        except asyncio.CancelledError:
            self.canceladas.append(producto)
            raise
        return PRECIOS[producto]

