import asyncio


async def procesar_lote(trabajos):
    nombres = list(trabajos)
    resultados = await asyncio.gather(*trabajos.values(), return_exceptions=True)
    exitos = {}
    errores = {}
    for nombre, resultado in zip(nombres, resultados):
        if isinstance(resultado, Exception):
            errores[nombre] = f"{type(resultado).__name__}: {resultado}"
        else:
            exitos[nombre] = resultado
    return exitos, errores

import asyncio


async def descargar_con_limite(urls, descargar, limite):
    if limite < 1:
        raise ValueError("limite debe ser al menos 1")
    semaforos = {}

    async def descargar_una(url):
        dominio = url.split("/")[0]
        if dominio not in semaforos:
            semaforos[dominio] = asyncio.Semaphore(limite)
        async with semaforos[dominio]:
            return await descargar(url)

    return await asyncio.gather(*(descargar_una(url) for url in urls))

