import asyncio

REINTENTABLES = (TimeoutError, ConnectionError)


async def con_reintentos(fabrica, intentos=3, limite=1.0, espera=0.0):
    if intentos < 1:
        raise ValueError("intentos debe ser al menos 1")
    for intento in range(1, intentos + 1):
        try:
            async with asyncio.timeout(limite):
                resultado = await fabrica()
            return resultado, intento
        except REINTENTABLES:
            if intento == intentos:
                raise
            await asyncio.sleep(espera * 2 ** (intento - 1))

