import asyncio


async def primero_en_responder(fuentes):
    if not fuentes:
        raise ValueError("Se necesita al menos una fuente")
    nombres = {asyncio.create_task(fabrica()): nombre for nombre, fabrica in fuentes.items()}
    pendientes = set(nombres)
    errores = []
    try:
        while pendientes:
            hechas, pendientes = await asyncio.wait(pendientes, return_when=asyncio.FIRST_COMPLETED)
            for tarea in hechas:
                if tarea.exception() is None:
                    return nombres[tarea], tarea.result()
                errores.append(tarea.exception())
        raise ExceptionGroup("todas las fuentes fallaron", errores)
    finally:
        for tarea in pendientes:
            tarea.cancel()
        await asyncio.gather(*pendientes, return_exceptions=True)

