import asyncio


class CacheAsincrona:
    def __init__(self, cargar):
        self._cargar = cargar
        self._valores = {}
        self._en_curso = {}

    async def obtener(self, clave):
        if clave in self._valores:
            return self._valores[clave]
        tarea = self._en_curso.get(clave)
        if tarea is None:
            tarea = asyncio.create_task(self._cargar_y_guardar(clave))
            self._en_curso[clave] = tarea
        return await asyncio.shield(tarea)

    async def _cargar_y_guardar(self, clave):
        try:
            valor = await self._cargar(clave)
            self._valores[clave] = valor
            return valor
        finally:
            del self._en_curso[clave]

    def invalidar(self, clave):
        self._valores.pop(clave, None)

