import asyncio
from contextlib import asynccontextmanager


class Pool:
    def __init__(self, crear, tamano):
        if tamano < 1:
            raise ValueError("El tamaño del pool debe ser al menos 1")
        self._crear = crear
        self._libres = []
        self._semaforo = asyncio.Semaphore(tamano)
        self.creadas = 0

    @asynccontextmanager
    async def conexion(self):
        async with self._semaforo:           # como mucho «tamano» en uso a la vez
            if self._libres:
                con = self._libres.pop()
            else:
                con = await self._crear()
                self.creadas += 1
            try:
                yield con
            finally:
                self._libres.append(con)     # vuelve al pool pase lo que pase

