import asyncio


async def rastrear(inicio, obtener, max_concurrencia=3, max_paginas=50, limite=1.0):
    if max_concurrencia < 1 or max_paginas < 1:
        raise ValueError("max_concurrencia y max_paginas deben ser al menos 1")
    cola = asyncio.Queue()
    vistas = {inicio}              # URL ya encoladas: evita repetir y controla el total
    visitadas = []
    errores = {}
    cola.put_nowait(inicio)

    async def trabajador():
        while True:
            url = await cola.get()
            try:
                async with asyncio.timeout(limite):
                    enlaces = await obtener(url)
            except Exception as error:
                errores[url] = type(error).__name__
            else:
                visitadas.append(url)
                for enlace in enlaces:
                    if enlace not in vistas and len(vistas) < max_paginas:
                        vistas.add(enlace)
                        cola.put_nowait(enlace)
            finally:
                cola.task_done()

    trabajadores = [asyncio.create_task(trabajador()) for _ in range(max_concurrencia)]
    try:
        await cola.join()
    finally:
        for tarea in trabajadores:
            tarea.cancel()
        await asyncio.gather(*trabajadores, return_exceptions=True)
    return {"visitadas": sorted(visitadas), "errores": errores}

