import asyncio
from dataclasses import dataclass


@dataclass(frozen=True)
class Pedido:
    id: int
    cliente: str
    importe: float


def parsear(linea):
    partes = [parte.strip() for parte in linea.split(";")]
    if len(partes) != 3:
        raise ValueError(f"se esperaban 3 campos: {linea!r}")
    id_texto, cliente, importe_texto = partes
    pedido_id = int(id_texto)              # ValueError si no es un entero
    importe = float(importe_texto)         # ValueError si no es un número
    if not cliente:
        raise ValueError("cliente vacío")
    if importe < 0:
        raise ValueError("importe negativo")
    return Pedido(pedido_id, cliente, importe)


async def fuente(lineas, intervalo=0.0):
    for linea in lineas:
        await asyncio.sleep(intervalo)
        linea = linea.strip()
        if linea:
            yield linea


async def procesar(lineas, verificar, n_trabajadores=3, capacidad=4):
    if n_trabajadores < 1 or capacidad < 1:
        raise ValueError("n_trabajadores y capacidad deben ser al menos 1")
    cola = asyncio.Queue(maxsize=capacidad)
    aceptados = []
    rechazados = []
    malformadas = 0

    async def productor():
        async for linea in fuente(lineas):
            await cola.put(linea)              # espera si la cola está llena
        cola.shutdown()                        # no habrá más líneas (3.13+)

    async def trabajador():
        nonlocal malformadas
        while True:
            try:
                linea = await cola.get()
            except asyncio.QueueShutDown:      # cerrada y vacía: fin
                return
            try:
                pedido = parsear(linea)
            except ValueError:
                malformadas += 1
                continue
            try:
                valido = await verificar(pedido)
            except Exception:
                valido = False
            if valido:
                aceptados.append(pedido)
            else:
                rechazados.append(pedido)

    async with asyncio.TaskGroup() as tg:
        tg.create_task(productor())
        for _ in range(n_trabajadores):
            tg.create_task(trabajador())

    por_cliente = {}
    for pedido in aceptados:
        por_cliente[pedido.cliente] = por_cliente.get(pedido.cliente, 0) + pedido.importe
    return {
        "aceptados": len(aceptados),
        "rechazados": sorted(pedido.id for pedido in rechazados),
        "malformadas": malformadas,
        "total": round(sum(pedido.importe for pedido in aceptados), 2),
        "por_cliente": {cliente: round(total, 2) for cliente, total in sorted(por_cliente.items())},
    }

